import { EditEventBase } from './edit-event-base';
/**
 * Represents the arguments for the `save` event.
 */
export class SaveEvent extends EditEventBase {
    /**
     * Provides the edited `formGroup` instance.
     */
    formGroup;
    /**
     * Provides the selected edit mode.
     */
    mode;
}
